class PasteButton{constructor(){this.init();}init(){const fields=document.querySelectorAll('.paste-trigger');fields.forEach(field=>{this.attachPasteButton(field);});this.observeNewFields();}attachPasteButton(field){if (field.dataset.pasteButtonAttached){return;}field.dataset.pasteButtonAttached='true';const wrapper=document.createElement('div');wrapper.className='paste-button-wrapper';const button=document.createElement('button');button.type='button';button.className='paste-button';button.title='اضغط للصق من الحافظة';button.innerHTML=`<svg class="paste-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"></path><rect x="8" y="2" width="8" height="4" rx="1" ry="1"></rect></svg>`;button.addEventListener('click',(e)=>{e.preventDefault();this.handlePaste(field,button);});if (field.getAttribute('data-paste-clean')){field.addEventListener('paste',(e)=>{const pastedText=(e.clipboardData||window.clipboardData).getData('text');if (pastedText){e.preventDefault();const cleaned=this.cleanPastedText(field,pastedText);field.value=cleaned;field.dispatchEvent(new Event('change',{bubbles:true}));field.dispatchEvent(new Event('input',{bubbles:true}));}});}field.parentNode.insertBefore(wrapper,field);wrapper.appendChild(field);wrapper.appendChild(button);}async handlePaste(field,button){try{let text=await navigator.clipboard.readText();text=this.cleanPastedText(field,text);field.value=text;field.dispatchEvent(new Event('change',{bubbles:true}));field.dispatchEvent(new Event('input',{bubbles:true}));this.showSuccess(button);field.focus();}catch(err){if (err.name==='NotAllowedError'){this.showError(button,'لا توجد صلاحيات للوصول للحافظة');}else if (err.name==='NotFoundError'){this.showError(button,'الحافظة فارغة');}else{this.showError(button,'حدث خطأ في اللصق');}}}cleanPastedText(field,text){const cleanType=field.getAttribute('data-paste-clean');if (cleanType==='slug'){return this.cleanSlugUrl(text);}return text;}cleanSlugUrl(text){let cleaned=text.trim();cleaned=cleaned.replace(/^https?:\/{2}/,'');const slashIndex=cleaned.indexOf('/');if (slashIndex!==-1){cleaned=cleaned.substring(slashIndex+1);}else{return this.decodeSlug(cleaned);}cleaned=cleaned.replace(/^\/+|\/+$/g,'');const parts=cleaned.split('/');cleaned=parts[parts.length-1];cleaned=this.decodeSlug(cleaned);return cleaned;}decodeSlug(text){try{return decodeURIComponent(text);}catch(e){return text;}}showSuccess(button){const originalHTML=button.innerHTML;button.classList.add('paste-button-success');button.innerHTML=`<svg class="paste-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"></polyline></svg>`;setTimeout(()=>{button.classList.remove('paste-button-success');button.innerHTML=originalHTML;},2000);}showError(button,message){const originalHTML=button.innerHTML;button.classList.add('paste-button-error');button.title=message;button.innerHTML=`<svg class="paste-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"></circle><line x1="12" y1="8" x2="12" y2="12"></line><line x1="12" y1="16" x2="12.01" y2="16"></line></svg>`;setTimeout(()=>{button.classList.remove('paste-button-error');button.innerHTML=originalHTML;button.title='اضغط للصق من الحافظة';},2000);}observeNewFields(){const observer=new MutationObserver((mutations)=>{mutations.forEach((mutation)=>{if (mutation.addedNodes.length){mutation.addedNodes.forEach((node)=>{if (node.nodeType===1){const newFields=node.querySelectorAll?.('.paste-trigger')||[];newFields.forEach(field=>{if (!field.dataset.pasteButtonAttached){this.attachPasteButton(field);}});if (node.classList?.contains('paste-trigger')&&!node.dataset.pasteButtonAttached){this.attachPasteButton(node);}}});}});});observer.observe(document.body,{childList:true,subtree:true});}}document.addEventListener('DOMContentLoaded',()=>{new PasteButton();});if (document.readyState==='loading'){document.addEventListener('DOMContentLoaded',()=>{new PasteButton();});}else{new PasteButton();}